// Canonical bilingual catalog. Copy is paraphrased from the linked official source,
// not presented as a verbatim brand slogan. Prices are CNY research fixtures.
import { productResearch } from './product-research.mjs';
export const checkedAt = '2026-10-07';
export const categories = [
  ['cat_digital', '数码电子', '📱', 1], ['cat_fashion', '服饰鞋包', '👟', 2],
  ['cat_home', '家居生活', '🏠', 3], ['cat_beauty', '美妆护肤', '✨', 4],
  ['cat_food', '食品饮料', '☕', 5],
];

const pair = (value) => value.split('|');
function p(number, brand, model, name, subtitle, description, specs, tag, sourceUrl, price) {
  const id = `prod_${String(number).padStart(3, '0')}`;
  const locales = ['zh', 'en'].map((locale, index) => ({
    locale, name: pair(name)[index], subtitle: pair(subtitle)[index], description: pair(description)[index],
    specs: Object.fromEntries([
      [index === 0 ? '品牌' : 'Brand', brand], [index === 0 ? '型号 / 系列' : 'Model / series', model],
      ...specs.map(([key, value]) => [pair(key)[index], pair(value)[index] ?? pair(value)[0]]),
    ]),
    tags: [pair(tag)[index], brand, model],
  }));
  return { id, brand, model, source_url: sourceUrl, source_checked_at: checkedAt, price, locales, research: productResearch[id] };
}

